import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.error('PAGEERROR', e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.locator('#start').click()
const debug = () => page.evaluate(() => window.__gameDebug())
const wait = ms => page.waitForTimeout(ms)
async function walkTo(name, x, z) {
  console.log('walk to', name, 'from', (await debug()).player)
  const deadline = Date.now() + 45000
  let lastLog = 0
  while (Date.now() < deadline) {
    const state = await debug()
    const [px, , pz] = state.player
    if (Math.hypot(x - px, z - pz) < 2.8) { await page.keyboard.up('w'); await page.keyboard.up('a'); await page.keyboard.up('s'); await page.keyboard.up('d'); console.log('arrived', name, state.player); return }
    const keys = []
    if (x - px > .5) keys.push('d'); else if (x - px < -.5) keys.push('a')
    if (z - pz > .5) keys.push('s'); else if (z - pz < -.5) keys.push('w')
    for (const k of ['w','a','s','d']) { if(keys.includes(k)) await page.keyboard.down(k); else await page.keyboard.up(k) }
    await wait(250)
    if (Date.now() - lastLog > 5000) { const s = await debug(); console.log('moving', name, s.player, 'suspicion', s.suspicion); lastLog = Date.now() }
  }
  for (const k of ['w','a','s','d']) await page.keyboard.up(k)
  throw new Error('failed to reach ' + name + ': ' + JSON.stringify(await debug()))
}
async function interact(name, x, z, answer) {
  await walkTo(name, x, z)
  await page.keyboard.press('e')
  await page.locator('#sceneDialogue button').waitFor({ state: 'visible', timeout: 5000 })
  await page.locator('#sceneDialogue button').click()
  await page.locator('#taskModal .choice').nth(answer).waitFor({ state: 'visible', timeout: 5000 })
  await page.locator('#taskModal .choice').nth(answer).click()
  await wait(350)
  console.log('interacted', name, await debug(), 'tasks', await page.locator('#taskCount').innerText())
  await wait(1600)
}
try {
 await interact('Centro Cívico',20,-17,0)
 await interact('Café Estrella',-17,-14,0)
 await interact('Correo Central',17,12,1)
 await interact('Mara',-13,-5,0)
 await interact('Leo',-7,12,0)
 await interact('Rosa',-15,16,0)
 await interact('Inés',7,-12,0)
 console.log('FINAL', await debug(), 'heading', await page.locator('#intro h1').innerText().catch(()=>''), 'tasks', await page.locator('#taskCount').innerText().catch(()=>''))
} finally { await browser.close() }

