import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.error('PAGEERROR', e.message))
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.locator('#start').click()
  const debug = () => page.evaluate(() => window.__gameDebug())
  const wait = ms => page.waitForTimeout(ms)
  // Walk to Mara and repeatedly give the first incorrect answer to exercise the suspicion lose state.
  const deadline = Date.now() + 30000
  while (Date.now() < deadline) {
    const [x,,z] = (await debug()).player
    if (Math.hypot(-13-x, -5-z) < 2.8) break
    const keys=[]
    if (-13-x > .5) keys.push('d'); else if (-13-x < -.5) keys.push('a')
    if (-5-z > .5) keys.push('s'); else if (-5-z < -.5) keys.push('w')
    for (const k of ['w','a','s','d']) { if(keys.includes(k)) await page.keyboard.down(k); else await page.keyboard.up(k) }
    await wait(250)
  }
  for (const k of ['w','a','s','d']) await page.keyboard.up(k)
  console.log('at Mara', (await debug()).player)
  for (let i=0;i<14;i++) {
    await page.keyboard.press('e')
    await page.locator('#sceneDialogue button').waitFor({state:'visible', timeout:5000})
    await page.locator('#sceneDialogue button').click()
    await page.locator('#taskModal .choice').nth(1).waitFor({state:'visible',timeout:5000})
    await page.locator('#taskModal .choice').nth(1).click()
    await wait(80)
    const s=await debug()
    console.log('wrong answer',i+1,'suspicion',s.suspicion)
    if (!s.started || s.suspicion >= 100) break
  }
  console.log('LOSE RESULT', await debug(), 'heading', await page.locator('#intro h1').innerText().catch(()=>''))

  // Start fresh and approach the first traffic lane from the side. The player should be able to move beside
